namespace sv_4334b8d2e9a542ca8283d52f6ec1541c.Services;

public enum Theme
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service that holds per-circuit (per-user) theme state.
/// All interactive components sharing the same circuit share this instance.
/// </summary>
public class ThemeService
{
    public Theme CurrentTheme { get; private set; } = Theme.System;
    public string AccentColor { get; private set; } = "#0d6efd";

    public event Action? OnChange;

    public void SetTheme(Theme theme)
    {
        if (CurrentTheme == theme) return;
        CurrentTheme = theme;
        NotifyStateChanged();
    }

    public void SetAccentColor(string color)
    {
        if (AccentColor == color) return;
        AccentColor = color;
        NotifyStateChanged();
    }

    public void SetAll(Theme theme, string accentColor)
    {
        CurrentTheme = theme;
        AccentColor = accentColor;
        NotifyStateChanged();
    }

    private void NotifyStateChanged() => OnChange?.Invoke();
}

@using sv_4334b8d2e9a542ca8283d52f6ec1541c.Services
@inject ThemeService ThemeService
@implements IDisposable

<span class="theme-indicator" title="Current theme">
    @GetThemeIcon() <span style="color: @ThemeService.AccentColor;">●</span>
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += StateHasChanged;
    }

    private string GetThemeIcon() => ThemeService.CurrentTheme switch
    {
        Theme.Light => "☀️",
        Theme.Dark => "🌙",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeService.OnChange -= StateHasChanged;
    }
}

@page "/settings"
@using sv_4334b8d2e9a542ca8283d52f6ec1541c.Services
@inject ThemeService ThemeService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card p-4" style="max-width: 400px;">
    <h4>Theme</h4>
    <div class="btn-group mb-3" role="group">
        @foreach (var theme in Enum.GetValues<Theme>())
        {
            <button class="btn @(ThemeService.CurrentTheme == theme ? "btn-primary" : "btn-outline-primary")"
                    @onclick="() => ThemeService.SetTheme(theme)">
                @theme
            </button>
        }
    </div>

    <h4>Accent Color</h4>
    <input type="color" class="form-control form-control-color mb-3"
           value="@ThemeService.AccentColor"
           @onchange="OnAccentColorChanged" />

    <div class="mt-3 p-3 border rounded">
        <strong>Preview:</strong>
        <span style="color: @ThemeService.AccentColor;">
            Theme is <strong>@ThemeService.CurrentTheme</strong>
        </span>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += StateHasChanged;
    }

    private void OnAccentColorChanged(ChangeEventArgs e)
    {
        ThemeService.SetAccentColor(e.Value?.ToString() ?? "#0d6efd");
    }

    public void Dispose()
    {
        ThemeService.OnChange -= StateHasChanged;
    }
}

